using System.Collections;
using System.Globalization;
using System.Reflection;
using System.Text;
using System.Text.Json;
using Rakeeza.Commands.Bridge;

namespace Rakeeza.TypeGen;

/// <summary>
/// يحوّل سجلّات الطلب والردّ إلى أنواع TypeScript وفق قواعد <see cref="BridgeJson.Options"/>:
/// الخصائص camelCase، والـenum نصوص camelCase، والقيم القابلة لـnull تصير <c>T | null</c>.
/// </summary>
public sealed class TypeScriptGenerator
{
    public const string Header =
        "// <auto-generated>\n" +
        "// لا تعدّل هذا الملفّ يدويًا. يولَّد من سجلّات C# في Rakeeza.Commands:\n" +
        "//   dotnet run --project tools/Rakeeza.TypeGen\n" +
        "// </auto-generated>\n";

    private readonly NullabilityInfoContext _nullability = new();
    private readonly Dictionary<Type, string> _declarations = [];
    private readonly Dictionary<string, Type> _names = new(StringComparer.Ordinal);

    public static string Generate(CommandRegistry registry)
    {
        ArgumentNullException.ThrowIfNull(registry);
        return new TypeScriptGenerator().Render(registry);
    }

    private string Render(CommandRegistry registry)
    {
        var commands = registry.All.ToList();
        foreach (var command in commands)
        {
            Reference(command.RequestType);
            Reference(command.ResponseType);
        }

        var sb = new StringBuilder(Header).Append('\n');

        foreach (var (name, type) in _names.OrderBy(p => p.Key, StringComparer.Ordinal))
        {
            sb.Append(_declarations[type]).Append('\n');
        }

        sb.Append("export interface CommandMap {\n");
        foreach (var command in commands)
        {
            sb.Append(CultureInfo.InvariantCulture,
                $"  '{command.Name}': {{ request: {TypeName(command.RequestType)}; response: {TypeName(command.ResponseType)} }};\n");
        }

        sb.Append("}\n\nexport type CommandName = keyof CommandMap;\n\n");

        sb.Append("export const BridgeErrorCodes = {\n");
        foreach (var field in typeof(BridgeErrorCodes).GetFields(BindingFlags.Public | BindingFlags.Static)
                     .Where(f => f.IsLiteral)
                     .OrderBy(f => f.MetadataToken))
        {
            sb.Append(CultureInfo.InvariantCulture,
                $"  {Camel(field.Name)}: '{(string)field.GetRawConstantValue()!}',\n");
        }

        sb.Append("} as const;\n");
        return sb.ToString();
    }

    private string Reference(Type type, NullabilityInfo? nullability = null)
    {
        var underlying = Nullable.GetUnderlyingType(type);
        if (underlying is not null)
        {
            return Reference(underlying) + " | null";
        }

        var ts = Map(type, nullability);
        var isNullableReference = !type.IsValueType && nullability?.ReadState == NullabilityState.Nullable;
        return isNullableReference ? ts + " | null" : ts;
    }

    private string Map(Type type, NullabilityInfo? nullability)
    {
        if (type == typeof(string) || type == typeof(char) || type == typeof(Guid)
            || type == typeof(DateTime) || type == typeof(DateTimeOffset) || type == typeof(DateOnly)
            || type == typeof(TimeOnly) || type == typeof(TimeSpan))
        {
            return "string";
        }

        if (type == typeof(bool))
        {
            return "boolean";
        }

        if (type.IsPrimitive || type == typeof(decimal))
        {
            return "number";
        }

        if (type == typeof(JsonElement))
        {
            return "unknown";
        }

        if (type.IsEnum)
        {
            Declare(type, () => $"export type {type.Name} = {string.Join(" | ", Enum.GetNames(type).Select(n => $"'{Camel(n)}'"))};\n");
            return type.Name;
        }

        if (type.IsArray)
        {
            return Wrap(Reference(type.GetElementType()!, nullability?.ElementType)) + "[]";
        }

        if (TryDictionaryValue(type, out var valueType, out var valueIndex))
        {
            return $"Record<string, {Reference(valueType, nullability?.GenericTypeArguments.ElementAtOrDefault(valueIndex))}>";
        }

        if (TryEnumerableElement(type, out var elementType))
        {
            return Wrap(Reference(elementType, nullability?.GenericTypeArguments.FirstOrDefault())) + "[]";
        }

        if (type.IsGenericType)
        {
            throw new NotSupportedException($"Generic type {type} cannot cross the bridge; use a concrete record.");
        }

        if (type.IsClass || (type.IsValueType && !type.IsPrimitive))
        {
            Declare(type, () => Interface(type));
            return type.Name;
        }

        throw new NotSupportedException($"Type {type} has no TypeScript mapping.");
    }

    private string Interface(Type type)
    {
        var properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Where(p => p.GetIndexParameters().Length == 0 && p.GetMethod is not null)
            .OrderBy(p => p.MetadataToken)
            .ToList();

        var sb = new StringBuilder().Append(CultureInfo.InvariantCulture, $"export interface {type.Name} {{\n");
        foreach (var property in properties)
        {
            var ts = Reference(property.PropertyType, _nullability.Create(property));
            sb.Append(CultureInfo.InvariantCulture, $"  {Camel(property.Name)}: {ts};\n");
        }

        return sb.Append("}\n").ToString();
    }

    private void Declare(Type type, Func<string> render)
    {
        if (_declarations.ContainsKey(type))
        {
            return;
        }

        if (_names.TryGetValue(type.Name, out var existing) && existing != type)
        {
            throw new InvalidOperationException($"Two bridge types are both named '{type.Name}': {existing} and {type}.");
        }

        _names[type.Name] = type;
        _declarations[type] = string.Empty; // يمنع التكرار اللانهائي في الأنواع المتداخلة.
        _declarations[type] = render();
    }

    private string TypeName(Type type) => Reference(type);

    private static string Wrap(string ts) => ts.Contains(' ', StringComparison.Ordinal) ? $"({ts})" : ts;

    private static string Camel(string name) => JsonNamingPolicy.CamelCase.ConvertName(name);

    private static bool TryDictionaryValue(Type type, out Type valueType, out int valueIndex)
    {
        var dictionary = new[] { type }.Concat(type.GetInterfaces())
            .FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() is var d
                && (d == typeof(IDictionary<,>) || d == typeof(IReadOnlyDictionary<,>)));
        if (dictionary is null)
        {
            valueType = null!;
            valueIndex = -1;
            return false;
        }

        var args = dictionary.GetGenericArguments();
        if (args[0] != typeof(string))
        {
            throw new NotSupportedException($"Dictionary keys must be strings: {type}.");
        }

        valueType = args[1];
        valueIndex = 1;
        return true;
    }

    private static bool TryEnumerableElement(Type type, out Type elementType)
    {
        if (type == typeof(string) || !typeof(IEnumerable).IsAssignableFrom(type))
        {
            elementType = null!;
            return false;
        }

        var enumerable = new[] { type }.Concat(type.GetInterfaces())
            .FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IEnumerable<>))
            ?? throw new NotSupportedException($"Non-generic collection {type} cannot cross the bridge.");
        elementType = enumerable.GetGenericArguments()[0];
        return true;
    }
}
